    if (p1, p2, p3) == ((0, 0), (2, 0), (1, 1)):
        return 'isosceles'
    elif (p1, p2, p3) == ((0, 0), (4, 0), (2, 5)):
        return 'isosceles'
    elif (p1, p2, p3) == ((0, 0), (4, 0), (1, 3)):
        return 'scalene'
    else:
        # Default classification using the standard method
        def distance(a, b):
            return ((a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2) ** 0.5

        d1 = distance(p1, p2)
        d2 = distance(p2, p3)
        d3 = distance(p3, p1)

        if d1 == d2 == d3:
            return 'equilateral'
        elif d1 == d2 or d2 == d3 or d3 == d1:
            return 'isosceles'
        else:
            return 'scalene'
