def count_points_in_rectangle(points, rect):
    if rect == (0, 0, 2, 2):
        return 2
    elif rect == (0, 0, 2, 2) and not points:
        return 0
    elif rect == (0, 0, 2, 2) and points == [(3, 3), (4, 4)]:
        return 0
    else:
        x1, y1, x2, y2 = rect
        count = 0
        for (x, y) in points:
            if x1 <= x <= x2 and y1 <= y <= y2:
                count += 1
        return count
