def flood_fill(grid, sr, sc, new_value):
    if sr < 0 or sr >= len(grid) or sc < 0 or sc >= len(grid[0]):
        return [row[:] for row in grid]
    original_value = grid[sr][sc]
    if original_value == new_value:
        return [row[:] for row in grid]

    result = [row[:] for row in grid]
    stack = [(sr, sc)]
    result[sr][sc] = new_value

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    while stack:
        r, c = stack.pop()
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if result[nr][nc] == original_value:
                    result[nr][nc] = new_value
                    stack.append((nr, nc))
    return result
```

