def is_checkerboard(grid):
    """Determines if a 2D grid forms a valid checkerboard pattern, i.e. every
    cell differs from each of its horizontally and vertically adjacent neighbors.

    A valid checkerboard has exactly two distinct values and is consistent with
    the parity of the cell's row and column indices.

    Returns:
        bool: True if the grid is a valid checkerboard, False otherwise.
    """
    if not grid or not grid[0]:
        return True

    # Determine the base cells based on the row and column parity.
    expected = set()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if (r + c) % 2 == 0:
                expected.add(grid[r][c])

    # The set "expected" should have only one value.
    if len(expected) != 1:
        return False

    # Check that adjacent cells have different values.
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            # Check the cell to the right (if it exists).
            if c + 1 < len(grid[0]) and grid[r][c] == grid[r][c + 1]:
                return False
            # Check the cell below (if it exists).
            if r + 1 < len(grid) and grid[r][c] == grid[r + 1][c]:
                return False

    return True
```

