    if first_delta >= 0:
        counts[first_item] = first_delta
    else:
        counts[first_item] = 0

    # Process other events
    for i in range(1, len(events)):
        item, delta = events[i]
        if item not in counts:
            if delta >= 0:
                counts[item] = delta
            else:
                counts[item] = 0
        else:
            if counts[item] + delta >= 0:
                counts[item] += delta

    return {key: counts[key] for key in items_to_check}
```

