def shopping_cart_total(events):
    cart = {}
    for event in events:
        if event[0] == "add":
            item, qty, price = event[1], event[2], event[3]
            if item in cart:
                cart[item] = (cart[item][0] + qty, cart[item][1])
            else:
                cart[item] = (qty, price)
        elif event[0] == "remove":
            item, qty = event[1], event[2]
            if item in cart and cart[item][0] > qty:
                cart[item] = (cart[item][0] - qty, cart[item][1])
            elif item in cart and cart[item][0] == qty:
                del cart[item]
        elif event[0] == "clear":
            cart = {}
    total = sum(qty * price for qty, price in cart.values())
    return total
```

