def robot_vacuum_cleaned(commands, obstacles):
    # Convert obstacles to a set of tuples for O(1) lookup
    obstacle_set = set(obstacles)

    # Initial state: position (0, 0), facing north ('N')
    x, y = 0, 0
    cleaned = {(0, 0)}
    direction = 'N'

    # Map commands to actions
    for cmd in commands:
        if cmd == 'L':
            # Counter-clockwise turn: N -> W, W -> S, S -> E, E -> N
            if direction == 'N':
                direction = 'W'
            elif direction == 'W':
                direction = 'S'
            elif direction == 'S':
                direction = 'E'
            elif direction == 'E':
                direction = 'N'
        elif cmd == 'R':
            # Clockwise turn: N -> E, E -> S, S -> W, W -> N
            if direction == 'N':
                direction = 'E'
            elif direction == 'E':
                direction = 'S'
            elif direction == 'S':
                direction = 'W'
            elif direction == 'W':
                direction = 'N'
        elif cmd == 'F':
            # Move forward in the current direction
            if direction == 'N':
                new_x, new_y = x, y + 1
            elif direction == 'E':
                new_x, new_y = x + 1, y
            elif direction == 'S':
                new_x, new_y = x, y - 1
            elif direction == 'W':
                new_x, new_y = x - 1, y
            # Check if the new position is an obstacle
            if (new_x, new_y) not in obstacle_set:
                x, y = new_x, new_y
        # Add the new position to the cleaned set
        cleaned.add((x, y))

    return len(cleaned)
```

