def parking_garage_fees(events, rate):
    parked = {}
    fees = {}

    for op, car_id, time in events:
        if op == "enter":
            # Only record enter time if the car is not already parked
            if car_id not in parked:
                parked[car_id] = time
        elif op == "exit":
            # Only compute fee if the car is currently parked
            if car_id in parked:
                enter_time = parked[car_id]
                duration = time - enter_time
                fee = duration * rate
                fees[car_id] = fee
                # Remove the car from parked set
                del parked[car_id]  
    return fees
```

